#pragma once
#include "preview.hpp"
#include <Native/GxUiVertices.hpp>
// Native draw path for original layout XY/RGBA8 geometry. Single base-level texture modulation is available; full TEV and GX state binding follow separately.
class NativeUiColorRenderer {
    ComPtr<ID3D11Device> device;ComPtr<ID3D11DeviceContext> context;
    ComPtr<ID3D11VertexShader> vs;ComPtr<ID3D11PixelShader> ps,texturedPs,intensityPs;ComPtr<ID3D11InputLayout> layout;ComPtr<ID3D11RasterizerState> rasterizer;
    ComPtr<ID3D11BlendState> sourceAlphaBlend;
public:
    explicit NativeUiColorRenderer(bool software=false){D3D_FEATURE_LEVEL level=D3D_FEATURE_LEVEL_11_0;dxCheck(D3D11CreateDevice(nullptr,software?D3D_DRIVER_TYPE_WARP:D3D_DRIVER_TYPE_HARDWARE,nullptr,0,&level,1,D3D11_SDK_VERSION,&device,nullptr,&context));
        const char* shader=R"(Texture2D source:register(t0);SamplerState sampling:register(s0);struct Vertex {float2 position:POSITION;float4 color:COLOR;float2 uv:TEXCOORD;};struct Varying {float4 position:SV_Position;float4 color:COLOR;float2 uv:TEXCOORD;};Varying vertex(Vertex v){Varying o;o.position=float4(v.position,0,1);o.color=v.color;o.uv=v.uv;return o;}float4 pixel(Varying v):SV_Target{return v.color;}float4 texturedPixel(Varying v):SV_Target{return source.Sample(sampling,v.uv)*v.color;}float4 intensityPixel(Varying v):SV_Target{return float4(v.color.rgb,source.Sample(sampling,v.uv).a*v.color.a);})";
        auto compile=[&](const char* entry,const char* profile){ComPtr<ID3DBlob> code,errors;auto result=D3DCompile(shader,std::strlen(shader),"native-ui-color",nullptr,nullptr,entry,profile,D3DCOMPILE_ENABLE_STRICTNESS,0,&code,&errors);if(FAILED(result))throw std::runtime_error(errors?std::string(static_cast<const char*>(errors->GetBufferPointer()),errors->GetBufferSize()):"UI shader compile failed");return code;};
        auto vertex=compile("vertex","vs_4_0"),pixel=compile("pixel","ps_4_0");dxCheck(device->CreateVertexShader(vertex->GetBufferPointer(),vertex->GetBufferSize(),nullptr,&vs));dxCheck(device->CreatePixelShader(pixel->GetBufferPointer(),pixel->GetBufferSize(),nullptr,&ps));
        auto textured=compile("texturedPixel","ps_4_0");dxCheck(device->CreatePixelShader(textured->GetBufferPointer(),textured->GetBufferSize(),nullptr,&texturedPs));auto intensity=compile("intensityPixel","ps_4_0");dxCheck(device->CreatePixelShader(intensity->GetBufferPointer(),intensity->GetBufferSize(),nullptr,&intensityPs));const D3D11_INPUT_ELEMENT_DESC elements[]={{"POSITION",0,DXGI_FORMAT_R32G32_FLOAT,0,0,D3D11_INPUT_PER_VERTEX_DATA,0},{"COLOR",0,DXGI_FORMAT_R32G32B32A32_FLOAT,0,8,D3D11_INPUT_PER_VERTEX_DATA,0},{"TEXCOORD",0,DXGI_FORMAT_R32G32_FLOAT,0,24,D3D11_INPUT_PER_VERTEX_DATA,0}};dxCheck(device->CreateInputLayout(elements,3,vertex->GetBufferPointer(),vertex->GetBufferSize(),&layout));D3D11_RASTERIZER_DESC raster{};raster.FillMode=D3D11_FILL_SOLID;raster.CullMode=D3D11_CULL_NONE;raster.DepthClipEnable=TRUE;dxCheck(device->CreateRasterizerState(&raster,&rasterizer));D3D11_BLEND_DESC blend{};auto& mode=blend.RenderTarget[0];mode.BlendEnable=TRUE;mode.SrcBlend=mode.SrcBlendAlpha=D3D11_BLEND_SRC_ALPHA;mode.DestBlend=mode.DestBlendAlpha=D3D11_BLEND_INV_SRC_ALPHA;mode.BlendOp=mode.BlendOpAlpha=D3D11_BLEND_OP_ADD;mode.RenderTargetWriteMask=D3D11_COLOR_WRITE_ENABLE_ALL;dxCheck(device->CreateBlendState(&blend,&sourceAlphaBlend));
    }
    struct Draw {std::array<Native::UiVertex,4> vertices;const TextureImage* texture=nullptr;bool alphaBlend=false;bool intensityFont=false;};
    TextureImage render(const std::array<Native::UiVertex,4>& quad,uint32_t width,uint32_t height,const TextureImage* texture=nullptr){return renderBatch({Draw{quad,texture}},width,height);}
    TextureImage renderBatch(const std::vector<Draw>& draws,uint32_t width,uint32_t height){assetCheck(width && height && width<=8192 && height<=8192 && draws.size()<=4096,"Invalid native UI batch");        D3D11_TEXTURE2D_DESC desc{};desc.Width=width;desc.Height=height;desc.MipLevels=1;desc.ArraySize=1;desc.Format=DXGI_FORMAT_R8G8B8A8_UNORM;desc.SampleDesc.Count=1;desc.BindFlags=D3D11_BIND_RENDER_TARGET;ComPtr<ID3D11Texture2D> target,staging;ComPtr<ID3D11RenderTargetView> view;dxCheck(device->CreateTexture2D(&desc,nullptr,&target));dxCheck(device->CreateRenderTargetView(target.Get(),nullptr,&view));float clear[4]={};context->ClearRenderTargetView(view.Get(),clear);auto rtv=view.Get();context->OMSetRenderTargets(1,&rtv,nullptr);D3D11_VIEWPORT viewport{0,0,float(width),float(height),0,1};context->RSSetViewports(1,&viewport);context->RSSetState(rasterizer.Get());
        for(const auto& draw:draws){const auto& quad=draw.vertices;auto texture=draw.texture;struct Vertex {float position[2],color[4],uv[2];};Vertex vertices[6];const unsigned order[]={0,1,2,0,2,3};for(unsigned i=0;i<6;++i){auto& source=quad[order[i]];assetCheck(std::isfinite(source.position[0]) && std::isfinite(source.position[1]),"Non-finite UI position");vertices[i].position[0]=2*source.position[0]/width-1;vertices[i].position[1]=1-2*source.position[1]/height;for(unsigned c=0;c<4;++c)vertices[i].color[c]=source.color[c]/255.f;for(unsigned u=0;u<2;++u){assetCheck(std::isfinite(source.uv[0][u]),"Non-finite UI UV");vertices[i].uv[u]=source.uv[0][u];}}
        ComPtr<ID3D11ShaderResourceView> resource;ComPtr<ID3D11SamplerState> sampler;if(texture){assetCheck(texture->width && texture->height && texture->width<=8192 && texture->height<=8192 && texture->pixels.size()==size_t(texture->width)*texture->height,"Invalid UI texture extent");assetCheck(texture->minFilter<=1 && texture->magFilter<=1 && texture->wrapS<=2 && texture->wrapT<=2,"UI base-level sampler required");D3D11_TEXTURE2D_DESC td{};td.Width=texture->width;td.Height=texture->height;td.MipLevels=1;td.ArraySize=1;td.Format=DXGI_FORMAT_R8G8B8A8_UNORM;td.SampleDesc.Count=1;td.Usage=D3D11_USAGE_IMMUTABLE;td.BindFlags=D3D11_BIND_SHADER_RESOURCE;D3D11_SUBRESOURCE_DATA data{texture->pixels.data(),texture->width*4,0};ComPtr<ID3D11Texture2D> image;dxCheck(device->CreateTexture2D(&td,&data,&image));dxCheck(device->CreateShaderResourceView(image.Get(),nullptr,&resource));auto address=[](unsigned mode){return mode==0?D3D11_TEXTURE_ADDRESS_CLAMP:mode==1?D3D11_TEXTURE_ADDRESS_WRAP:D3D11_TEXTURE_ADDRESS_MIRROR;};D3D11_SAMPLER_DESC s{};s.Filter=D3D11_FILTER((texture->minFilter?0x10:0)|(texture->magFilter?4:0));s.AddressU=address(texture->wrapS);s.AddressV=address(texture->wrapT);s.AddressW=D3D11_TEXTURE_ADDRESS_CLAMP;s.MaxLOD=0;dxCheck(device->CreateSamplerState(&s,&sampler));}auto srv=resource.Get();auto smp=sampler.Get();context->PSSetShaderResources(0,1,&srv);context->PSSetSamplers(0,1,&smp);D3D11_BUFFER_DESC bufferDesc{};bufferDesc.ByteWidth=sizeof(vertices);bufferDesc.Usage=D3D11_USAGE_IMMUTABLE;bufferDesc.BindFlags=D3D11_BIND_VERTEX_BUFFER;D3D11_SUBRESOURCE_DATA source{vertices,0,0};ComPtr<ID3D11Buffer> buffer;dxCheck(device->CreateBuffer(&bufferDesc,&source,&buffer));
UINT stride=sizeof(Vertex),offset=0;auto vb=buffer.Get();context->IASetVertexBuffers(0,1,&vb,&stride,&offset);context->IASetInputLayout(layout.Get());context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);context->VSSetShader(vs.Get(),nullptr,0);context->PSSetShader(texture?(draw.intensityFont?intensityPs.Get():texturedPs.Get()):ps.Get(),nullptr,0);context->OMSetBlendState(draw.alphaBlend?sourceAlphaBlend.Get():nullptr,nullptr,0xffffffff);context->Draw(6,0);}context->OMSetRenderTargets(0,nullptr,nullptr);
        desc.BindFlags=0;desc.Usage=D3D11_USAGE_STAGING;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ;dxCheck(device->CreateTexture2D(&desc,nullptr,&staging));context->CopyResource(staging.Get(),target.Get());D3D11_MAPPED_SUBRESOURCE mapped{};dxCheck(context->Map(staging.Get(),0,D3D11_MAP_READ,0,&mapped));TextureImage output{width,height,6,std::vector<Pixel>(size_t(width)*height)};for(unsigned y=0;y<height;++y)std::memcpy(output.pixels.data()+size_t(y)*width,static_cast<uint8_t*>(mapped.pData)+size_t(y)*mapped.RowPitch,width*4);context->Unmap(staging.Get(),0);return output;
    }
};




